import React, { useEffect, useState } from 'react'
import { Table, Spinner, Container } from "react-bootstrap";
import { useNavigate } from 'react-router-dom'
import { useAccount, useNetwork, useSwitchNetwork } from 'wagmi'
import { ethers } from "ethers"
import Account from './Account';
import { supportDespoitChains, supportWithdrawChains } from '../../constants/networks';
import { DepositTokens, contracts } from '../../constants/contracts';
import CloseSvg from '../../assets/images/close.svg';
import WithdrawButton from '../common/WithdrawButton';
const optimismSDK = require("@eth-optimism/sdk")

const messageMap = {
    6: 'Completed',
    5: 'Claim Withdrawal',
    4: 'In challenge Period',
    3: 'Ready to Prove',
    2: 'Waiting for Confirmation',
}

const WithdrawAccount = () => {
    const [transactionLoader, setTransactionLoader] = useState(false);
    const [loader, setLoader] = useState();
    const { address, isConnected } = useAccount();
    const { chain } = useNetwork();
    const [withdrawDetails, setWithdrawDetails] = useState([]);
    const { switchNetworkAsync } = useSwitchNetwork();
    const navigate = useNavigate();
    const getWithdraw = async () => {
        let list = [];
        for (const l1Chain of supportDespoitChains) {
            const l2Chain = supportWithdrawChains.find(({ l1ChainId }) => l1ChainId === l1Chain.id);
            const [l1Url] = l1Chain.rpcUrls.default.http;
            const [l2Url] = l2Chain.rpcUrls.default.http;
            const l1Provider = new ethers.providers.JsonRpcProvider(l1Url);
            const l2Provider = new ethers.providers.JsonRpcProvider(l2Url);
    
            const l1Signer = l1Provider.getSigner(address)
            const l2Signer = l2Provider.getSigner(address)
            const l1Contracts = contracts[l1Chain.id];
    
            const bridges = {
                Standard: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.StandardBridgeAdapter
                },
                ETH: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.ETHBridgeAdapter
                }
            }
            const crossChainMessenger = new optimismSDK.CrossChainMessenger({
                contracts: {
                    l1: l1Contracts,
                },
                bridges: bridges,
                l1ChainId: l1Chain.id,
                l2ChainId: l2Chain.id,
                l1SignerOrProvider: l1Signer,
                l2SignerOrProvider: l2Signer,
                bedrock: true,
            })
            const data = await crossChainMessenger.getWithdrawalsByAddress(address)
            for (let index = 0; index < data.length; index++) {
                const timestamp = data[index].timestamp || (await l2Provider.getBlock(data[index].blockNumber)).timestamp;
                const getStatus = await crossChainMessenger.getMessageStatus(data[index].transactionHash);
                data[index].messageStatus = getStatus
                data[index].timestamp = timestamp
                data[index].blockExplorer = l2Chain.blockExplorers.default.url;
                data[index].chainId = l1Chain.id;
                data[index].message = messageMap[getStatus] || null;
                data[index].tokenSymbol = 'ETH';
                for (const token of DepositTokens) {
                    if (token.address.toLowerCase() === data[index].l1Token.toLowerCase()) {
                        data[index].tokenSymbol = token.symbol;
                        data[index].decimals = token.decimals;
                    }
                }
            }
            list = list.concat(data);
        }
        list = list.sort((x, y) => y.timestamp - x.timestamp);
        setWithdrawDetails(list);
        setTransactionLoader(true);
    }

    function timeConverter(timestamp) {
        var a = new Date(timestamp * 1000);
        var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        var year = a.getFullYear();
        var month = months[a.getMonth()];
        var date = a.getDate();
        var hour = a.getHours();
        var min = a.getMinutes();
        var sec = a.getSeconds();
        var time = date + ' ' + month + ' ' + year + ' ' + hour + ':' + min + ':' + sec;
        return time;
    }

    const getCrossChainMessenger = async (chainId) => {
        try {
            const l2Chain = supportWithdrawChains.find(({ l1ChainId }) => l1ChainId === chainId);
            const [l2Url] = l2Chain.rpcUrls.default.http;
            const l1Provider = new ethers.providers.Web3Provider(window.ethereum, "any");
            const l2Provider = new ethers.providers.JsonRpcProvider(l2Url);
            const l1Signer = l1Provider.getSigner(address)
            const l2Signer = l2Provider.getSigner(address)
            const l1Contracts = contracts[chainId];
    
            const bridges = {
                Standard: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.StandardBridgeAdapter
                },
                ETH: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.ETHBridgeAdapter
                }
            }
            return new optimismSDK.CrossChainMessenger({
                contracts: {
                    l1: l1Contracts,
                },
                bridges: bridges,
                l1ChainId: chainId,
                l2ChainId: l2Chain.id,
                l1SignerOrProvider: l1Signer,
                l2SignerOrProvider: l2Signer,
                bedrock: true,
            })
        } catch (error) {
            return null;
        }
    }

    const handleProve = async (index, transactionHash, chainId) => {
        try {
            if (chain.id !== chainId) {
                await switchNetworkAsync(chainId);
            }
            setLoader(index)
            const crossChainMessenger = await getCrossChainMessenger(chainId);
            const response = await crossChainMessenger.proveMessage(transactionHash)
            const logs = await response.wait()
            if (logs.status === 1) {
                setWithdrawDetails([]);
                setTransactionLoader(false);
                getWithdraw()
                setLoader(NaN)
            }
        } catch (error) {
            if (error.code === "ACTION_REJECTED") {
                setLoader(NaN)
            }
        }
    }

    const handleClaim = async (index, transactionHash, chainId) => {
        try {
            if (chain.id !== chainId) {
                await switchNetworkAsync(chainId);
            }
            setLoader(index)
            const crossChainMessenger = await getCrossChainMessenger(chainId);
            const response = await crossChainMessenger.finalizeMessage(transactionHash);
            const logs = await response.wait()
            if (logs.status === 1) {
                setWithdrawDetails([]);
                setTransactionLoader(false);
                getWithdraw()
                setLoader(NaN)
            }
        } catch (error) {
            if (error.code === "ACTION_REJECTED") {
                setLoader(NaN)
            }
        }
    }

    useEffect(() => {
        if (isConnected) {
            getWithdraw()
        }
    }, [address])
    // =============all Collections pagination start===============
    // const [currentItemsCollections, setCurrentItemsCollections] = useState([]);
    // const [pageCountCollections, setPageCountCollections] = useState(0);
    // const [itemOffsetCollections, setItemOffsetCollections] = useState(0);
    // const itemsPerPageCollections = 10;

    function retrieveEthValue(amount, decimals = '18') {
        const weiValue = parseInt(amount._hex, 16);
        return weiValue / Number("1".padEnd(+(decimals) + 1, 0));
    }

    const getMessageStatus = async (chainId, transactionHash) => {
        try {
            const l1Chain = supportDespoitChains.find(({ id }) => id === chainId);
            const l2Chain = supportWithdrawChains.find(({ l1ChainId }) => l1ChainId === chainId);
            const [l1Url] = l1Chain.rpcUrls.default.http;
            const [l2Url] = l2Chain.rpcUrls.default.http;
            const l1Provider = new ethers.providers.JsonRpcProvider(l1Url);
            const l2Provider = new ethers.providers.JsonRpcProvider(l2Url);
    
            const l1Signer = l1Provider.getSigner(address)
            const l2Signer = l2Provider.getSigner(address)
            const l1Contracts = contracts[chainId];
    
            const bridges = {
                Standard: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.StandardBridgeAdapter
                },
                ETH: {
                    l1Bridge: l1Contracts.L1StandardBridge,
                    l2Bridge: l1Contracts.L2Bridge,
                    Adapter: optimismSDK.ETHBridgeAdapter
                }
            }
            const crossChainMessenger = new optimismSDK.CrossChainMessenger({
                contracts: {
                    l1: l1Contracts,
                },
                bridges: bridges,
                l1ChainId: l1Chain.id,
                l2ChainId: l2Chain.id,
                l1SignerOrProvider: l1Signer,
                l2SignerOrProvider: l2Signer,
                bedrock: true,
            })
            const getStatus = await crossChainMessenger.getMessageStatus(transactionHash);
            console.log(getStatus);
            return getStatus;
        } catch (error) {
            console.log(error);
            return null;
        }
    }

    // useEffect(() => {
    //     if (withdrawDetails) {
    //         const endOffsetCollections = itemOffsetCollections + itemsPerPageCollections;
    //         setCurrentItemsCollections(withdrawDetails.slice(itemOffsetCollections, endOffsetCollections));
    //         setPageCountCollections(Math.ceil(withdrawDetails.length / itemsPerPageCollections));
    //     } else {

    //     }
    // }, [withdrawDetails, itemOffsetCollections, itemsPerPageCollections]);

    // const handlePageClickCollections = (event) => {
    //     const newOffsetCollections =
    //         (event.selected * itemsPerPageCollections) % withdrawDetails.length;
    //     setItemOffsetCollections(newOffsetCollections);
    // };
    // =============all Collections pagination end===============
    // console.log("withdrawDetails", {currentItemsCollections, withdrawDetails});
    return (
        <>
            <div className="account_wrap">
                <Container>
                    <div className='account_inner_wrap'>
                        <div className="close-btn" onClick={() => navigate('/deposit')}>
                            <img src={CloseSvg} />
                        </div>
                        <Account />
                        <section className="account_withdraw_table">
                            {
                                !transactionLoader ? <div className="lds-ellipsis"><div></div><div></div><div></div><div></div></div> :
                                    withdrawDetails?.length <= 0 ? <h4 className='text-center text-white'>No Transaction Found</h4> :
                                        <Table responsive bordered hover variant="dark">
                                            <thead>
                                                <tr>
                                                    <th>Time</th>
                                                    <th>Type</th>
                                                    <th>Amount</th>
                                                    <th>Transaction</th>
                                                    <th>Status</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {withdrawDetails.map((element, index) => {
                                                    const { timestamp, message, transactionHash, amount, messageStatus, blockExplorer, chainId, tokenSymbol, decimals } = element
                                                    return (
                                                        <tr key={index}>
                                                            <td><div className="account_withdraw_td">{timeConverter(timestamp)}</div></td>
                                                            <td><div className="account_withdraw_td">Withdraw</div></td>
                                                            <td><div className="account_withdraw_td">{retrieveEthValue(amount, decimals)} {tokenSymbol}</div></td>
                                                            <td>
                                                                <div className="account_withdraw_td">
                                                                    <a href={`${blockExplorer}/tx/${transactionHash}`} target='_blank'> {`${transactionHash.slice(0, 8)}...${transactionHash.slice(-8)}`}</a>
                                                                </div>
                                                            </td>
                                                            <td>
                                                                <div className="account_withdraw_td">
                                                                    <WithdrawButton
                                                                        loading={index == loader}
                                                                        messageStatus={messageStatus}
                                                                        handleProve={() => handleProve(index, transactionHash, chainId)}
                                                                        handleClaim={() => handleClaim(index, transactionHash, chainId)}
                                                                        updateStatus={() => getMessageStatus(chainId, transactionHash)}
                                                                    />
                                                                </div>
                                                            </td>
                                                        </tr>
                                                    )
                                                })}

                                            </tbody>
                                        </Table>}
                            {/* {withdrawDetails?.length > 10 ? <div className='pagination_wrap'>
                                <ReactPaginate
                                    breakLabel="..."
                                    nextLabel=" >>"
                                    onPageChange={handlePageClickCollections}
                                    pageRangeDisplayed={1}
                                    marginPagesDisplayed={1}
                                    pageCount={pageCountCollections}
                                    previousLabel="<< "
                                    containerClassName="pagination justify-content-end"
                                    pageClassName="page-item"
                                    pageLinkClassName="page-link"
                                    previousClassName="page-item"
                                    previousLinkClassName="page-link"
                                    nextClassName="page-item"
                                    nextLinkClassName="page-link"
                                    breakClassName="page-item"
                                    breakLinkClassName="page-link"
                                    activeClassName="active"
                                />
                            </div> : ""} */}
                        </section>
                    </div>
                </Container>
            </div>
        </>
    )
}

export default WithdrawAccount