import { LineaNetwork, ZytronLinea } from "../constants/networks";
import { useAccount, useBalance } from 'wagmi'
import { Tokens } from '../constants/contracts';

const useAccountBalance = () => {
  const { address } = useAccount();
  const lineaUsdt = useBalance({ address: address, token: Tokens.USDT[LineaNetwork.id].address, watch: true, chainId: LineaNetwork.id });
  const lineaUsdcE = useBalance({ address: address, token: Tokens["USDC_E"][LineaNetwork.id].address, watch: true, chainId: LineaNetwork.id });
  const lineaGp = useBalance({ address: address, token: Tokens.GP[LineaNetwork.id].address, watch: true, chainId: LineaNetwork.id });
  const lineaETH = useBalance({ address: address, watch: true, chainId: LineaNetwork.id });

  const lineaL3Usdt = useBalance({ address: address, token: Tokens.USDT[ZytronLinea.id].address, watch: true, chainId: ZytronLinea.id });
  const lineaL3UsdcE = useBalance({ address: address, token: Tokens["USDC_E"][ZytronLinea.id].address, watch: true, chainId: ZytronLinea.id });
  const lineaL3Gp = useBalance({ address: address, token: Tokens.GP[ZytronLinea.id].address, watch: true, chainId: ZytronLinea.id });
  const lineaL3ETH = useBalance({ address: address, watch: true, chainId: ZytronLinea.id });

  return {
    [LineaNetwork.id]: {
      eth: lineaETH,
      gp: lineaGp,
      usdt: lineaUsdt,
      ['usdc_e']: lineaUsdcE,
    },
    [ZytronLinea.id]: {
      eth: lineaL3ETH,
      gp: lineaL3Gp,
      usdt: lineaL3Usdt,
      ['usdc_e']: lineaL3UsdcE,
    },
  }
}

export default useAccountBalance;
